arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "types=public_channel,private_channel" -d "exclude_archived=true" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d); sys.exit(0)
for c in d['channels']:
    if 'incident' in c.get('name','').lower():
        print(c['id'], c['name'], c.get('is_archived'))
"

