arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d); sys.exit(0)
for u in d['members']:
    prof = u.get('profile') or {}
    print(u['id'], '|', u.get('real_name'), '| title:', prof.get('title'), '| loc:', prof.get('location'), '| deleted:', u.get('deleted'), '| status:', (prof.get('status_text') or '')[:60])
"

